// Artwork stays in its original reference coordinates. All game geometry is
// Terrain and buildings use independent scales, so a shorter river never shrinks homes.
const MAP_RATIO=.16,BUILDING_RATIO=.25,MAP_FACTOR=7*MAP_RATIO;
const WORLD_WIDTH=1536*MAP_FACTOR,WORLD_HEIGHT=1024*MAP_FACTOR;
const mapUnit=n=>n*MAP_RATIO;
const buildingUnit=n=>n*BUILDING_RATIO;
const storefrontScale=1.2;
function compactVillage(raw){return raw.map(v=>({...v,x:mapUnit(v.x),y:mapUnit(v.y),w:buildingUnit(v.w)*storefrontScale,h:buildingUnit(v.h)*storefrontScale,doorX:mapUnit(v.x)+buildingUnit(v.doorX-v.x),doorY:mapUnit(v.y)+buildingUnit(v.doorY-v.y)}))}
function compactDetail(raw,town=raw.houses){return{
 water:raw.water.map(poly=>poly.map(p=>p.map(mapUnit))),
 roads:raw.roads.map(line=>line.map(p=>p.map(mapUnit))),
 houses:town.map(([x,y,w,h])=>[mapUnit(x),mapUnit(y),buildingUnit(w),buildingUnit(h)]),
 trees:raw.trees.map(([x,y,r,type])=>[mapUnit(x),mapUnit(y),mapUnit(r),type])
}}

