function spotlightForTime(now){
  const slotNow=Math.floor(now/UNIQUE_ROTATION_MS),active=now-slotNow*UNIQUE_ROTATION_MS<UNIQUE_WINDOW_MS;
  const slot=active?slotNow:slotNow+1;   // pendant la pause : le prochain poisson est déjà annoncé
  const template=UNIQUE_FISHES[((slot%UNIQUE_FISHES.length)+UNIQUE_FISHES.length)%UNIQUE_FISHES.length];
  const zone=FISH_ZONES.find(z=>z.id===template.zone)||FISH_ZONES[0];
  const startAt=slot*UNIQUE_ROTATION_MS;
  const zoneNumber=Math.max(0,FISH_ZONES.findIndex(z=>z.id===zone.id))+1;
  return {
    key:slot+':'+template.title,
    slot,
    active,
    startAt,
    endAt:startAt+UNIQUE_WINDOW_MS,
    nextAt:startAt+UNIQUE_ROTATION_MS,
    minutes:Math.round(UNIQUE_WINDOW_MS/60000),
    everyMinutes:Math.round(UNIQUE_ROTATION_MS/60000),
    chance:UNIQUE_BASE_CHANCE,
    reward:{coins:900,xp:650},
    zoneId:zone.id,
    zoneName:zone.name,
    zoneNumber,
    zoneTargets:zone.targets,
    species:template.species,
    title:template.title,
    color:template.color,
    accent:template.accent,
    size:template.size,
    spot:template.species+' unique · '+zone.name,
    spawnHint:'Zone n° '+zoneNumber+' · '+zone.name
  };
}
