function riverPosition(x,y){let total=0,best={distance:Infinity,s:0};for(let i=1;i<RIVER_COURSE.length;i++){const a=RIVER_COURSE[i-1],b=RIVER_COURSE[i],dx=(b[0]-a[0])*MAP_FACTOR,dy=(b[1]-a[1])*MAP_FACTOR,len=Math.hypot(dx,dy);const t=Math.max(0,Math.min(1,((x-a[0]*MAP_FACTOR)*dx+(y-a[1]*MAP_FACTOR)*dy)/(len*len||1)));const distance=Math.hypot(x-a[0]*MAP_FACTOR-t*dx,y-a[1]*MAP_FACTOR-t*dy);if(distance<best.distance)best={distance,s:total+t*len};total+=len}return{...best,fraction:best.s/total}}
