// Reuse successful identity checks briefly during position updates.
const sessions = new Map();
async function participant(request) {
 const authorization = request.headers.get('authorization') || '';
 if (!/^Bearer [^ ]{1,8192}$/.test(authorization)) return null;
 const known = sessions.get(authorization);
 if (known && known.until > Date.now()) return known.id;
 const result = await fetch(SUPABASE_URL + '/auth/v1/user', {headers:{apikey:SUPABASE_KEY, Authorization:authorization}});
 if (result.status === 401 || result.status === 403) return null;
 if (!result.ok) throw new Error('Service de connexion indisponible');
 const {id} = await result.json();
 if (typeof id !== 'string' || !id) return null;
 if (sessions.size >= 512) sessions.clear();
 sessions.set(authorization,{id,until:Date.now()+15000});
 return id;
}
const guestCookieName='__Host-street-fishing-guest';
function hex(bytes){
  return Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');
}
async function browserGuest(request,create){
  const stored=(request.headers.get('cookie')||'').match(/(?:^|;\s*)__Host-street-fishing-guest=([a-f0-9]{64})(?=;|$)/);
  if(!stored&&!create)return null;
  const token=stored?stored[1]:hex(crypto.getRandomValues(new Uint8Array(32)));
  const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token));
  return {id:'guest:'+hex(new Uint8Array(hash)),cookie:stored?null:
    guestCookieName+'='+token+'; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=31536000'};
}
