const parisDate=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'});
const parisHour=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Paris',hour:'2-digit',hourCycle:'h23'});
function questDay(now){
  const day=parisDate.format(now);
  const utc=Date.parse(day+'T00:00:00Z');
  // In Paris, midnight UTC falls one or two hours after the local midnight.
  const midnight=utcDay=>utcDay-Number(parisHour.format(utcDay))*3600000;
  return {day,start:midnight(utc),resetAt:midnight(utc+86400000)};
}
async function questList(db,id,period){
  const stats=await db.prepare(`SELECT COUNT(*) AS fish,COUNT(DISTINCT spot) AS spots,COUNT(DISTINCT name) AS species,
    SUM(CASE WHEN name='Perche' THEN 1 ELSE 0 END) AS perches,
    SUM(CASE WHEN name='Brochet' THEN 1 ELSE 0 END) AS brochets,
    SUM(CASE WHEN name='Sandre' THEN 1 ELSE 0 END) AS sandres,
    COUNT(CASE WHEN size>=CASE name ${SPECIES.map(f=>"WHEN '"+f.name+"' THEN "+f.trophy).join(' ')} ELSE 999999 END THEN 1 END) AS trophies
    FROM captures WHERE player_id=? AND created>=? AND created<?`).bind(id,period.start,period.resetAt).first();
  const {results}=await db.prepare('SELECT quest FROM daily_quest_claims WHERE player_id=? AND day=?').bind(id,period.day).all();
  const lifetime=await db.prepare(`SELECT COUNT(*) AS fish,COUNT(DISTINCT spot) AS spots,COUNT(DISTINCT name) AS species,
    COUNT(CASE WHEN size>=CASE name ${SPECIES.map(f=>"WHEN '"+f.name+"' THEN "+f.trophy).join(' ')} ELSE 999999 END THEN 1 END) AS trophies
    FROM captures WHERE player_id=?`).bind(id).first();
  const careerClaims=await db.prepare("SELECT quest FROM daily_quest_claims WHERE player_id=? AND day='career'").bind(id).all();
  const career=careerGoals.map(q=>({...q,career:true,progress:Math.min(q.target,lifetime[q.metric]),claimed:careerClaims.results.some(r=>r.quest===q.key)}));
  return quests.concat(dailyChallenges).map(q=>({...q,progress:Math.min(q.target,Number(stats[q.metric]||0)),claimed:results.some(r=>r.quest===q.key)})).concat(career);
}
