// Duels: the database performs wager debits and payouts in atomic triggers.
schema.push(
  "CREATE TABLE IF NOT EXISTS duels (id TEXT PRIMARY KEY, challenger TEXT NOT NULL, opponent TEXT, opponent_name TEXT NOT NULL, bot INTEGER NOT NULL DEFAULT 0, wager INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','done','rejected','expired')), created INTEGER NOT NULL, started INTEGER NOT NULL DEFAULT 0, ends INTEGER NOT NULL DEFAULT 0, challenger_score INTEGER DEFAULT 0, opponent_score INTEGER DEFAULT 0, winner TEXT DEFAULT '', bot_score INTEGER DEFAULT 0)",
  "CREATE INDEX IF NOT EXISTS duels_challenger ON duels(challenger,created DESC)",
  "CREATE INDEX IF NOT EXISTS duels_opponent ON duels(opponent,created DESC)",
  "DROP TRIGGER IF EXISTS duel_start_guard",
  "CREATE TRIGGER IF NOT EXISTS duel_start_guard BEFORE UPDATE OF status ON duels WHEN NEW.status='active' AND OLD.status='pending' BEGIN SELECT CASE WHEN COALESCE((SELECT coins FROM players WHERE id=NEW.challenger),-1)<NEW.wager OR (NEW.bot=0 AND COALESCE((SELECT coins FROM players WHERE id=NEW.opponent),-1)<NEW.wager) THEN RAISE(ABORT,'Mise insuffisante pour démarrer ce duel') END; END",
  "CREATE TRIGGER IF NOT EXISTS duel_start_debit AFTER UPDATE OF status ON duels WHEN NEW.status='active' AND OLD.status='pending' BEGIN UPDATE players SET coins=coins-NEW.wager WHERE id=NEW.challenger; UPDATE players SET coins=coins-NEW.wager WHERE id=NEW.opponent AND NEW.bot=0; END",
  "CREATE TRIGGER IF NOT EXISTS duel_settle AFTER UPDATE OF status ON duels WHEN NEW.status='done' AND OLD.status='active' BEGIN UPDATE players SET coins=coins+CASE WHEN NEW.winner='challenger' THEN 2*NEW.wager WHEN NEW.winner='tie' THEN NEW.wager ELSE 0 END WHERE id=NEW.challenger; UPDATE players SET coins=coins+CASE WHEN NEW.winner='opponent' THEN 2*NEW.wager WHEN NEW.winner='tie' THEN NEW.wager ELSE 0 END WHERE id=NEW.opponent AND NEW.bot=0; END",
  "CREATE TRIGGER IF NOT EXISTS duel_profile_cleanup AFTER DELETE ON players BEGIN DELETE FROM duels WHERE challenger=OLD.id OR opponent=OLD.id; END",
  "CREATE TRIGGER IF NOT EXISTS duel_overlap_guard BEFORE UPDATE OF status ON duels WHEN NEW.status='active' AND OLD.status='pending' AND EXISTS(SELECT 1 FROM duels WHERE id<>NEW.id AND status='active' AND (challenger IN (NEW.challenger,NEW.opponent) OR opponent IN (NEW.challenger,NEW.opponent))) BEGIN SELECT RAISE(ABORT,'Un joueur a déjà un duel actif'); END"
);
schema.push("DROP TRIGGER IF EXISTS duel_bot_reward");
schema.push("CREATE TRIGGER IF NOT EXISTS duel_bot_reward AFTER UPDATE OF status ON duels WHEN NEW.status='done' AND OLD.status='active' AND NEW.bot=1 AND NEW.wager=0 AND NEW.winner IN ('challenger','tie') BEGIN UPDATE players SET coins=coins+(CASE substr(NEW.opponent_name,12,1) WHEN '1' THEN 20 WHEN '2' THEN 45 WHEN '3' THEN 90 WHEN '4' THEN 160 ELSE 0 END)/(CASE WHEN NEW.winner='tie' THEN 2 ELSE 1 END),xp=xp+(CASE substr(NEW.opponent_name,12,1) WHEN '1' THEN 30 WHEN '2' THEN 65 WHEN '3' THEN 135 WHEN '4' THEN 240 ELSE 0 END)/(CASE WHEN NEW.winner='tie' THEN 2 ELSE 1 END) WHERE id=NEW.challenger; END");
// Récompense du vainqueur (duel humain sans mise) : rang calculé AVANT ce duel, plafonds quotidiens.
{
  const W="(CASE NEW.winner WHEN 'challenger' THEN NEW.challenger ELSE NEW.opponent END)";
  const L="(CASE NEW.winner WHEN 'challenger' THEN NEW.opponent ELSE NEW.challenger END)";
  const ratingBefore="COALESCE((SELECT MAX(0,SUM(r='w')*"+DUEL_POINTS.win+"+SUM(r='l')*("+DUEL_POINTS.loss+")+SUM(r='t')*"+DUEL_POINTS.tie+") FROM (SELECT CASE winner WHEN 'challenger' THEN 'w' WHEN 'opponent' THEN 'l' ELSE 't' END AS r FROM duels WHERE status='done' AND bot=0 AND id<>NEW.id AND challenger="+W+" UNION ALL SELECT CASE winner WHEN 'opponent' THEN 'w' WHEN 'challenger' THEN 'l' ELSE 't' END AS r FROM duels WHERE status='done' AND bot=0 AND id<>NEW.id AND opponent="+W+")),0)";
  const byRank=field=>"(CASE "+[...DUEL_RANKS].reverse().map(r=>"WHEN "+ratingBefore+">="+r.min+" THEN "+r[field]).join(" ")+" ELSE 0 END)";
  const dayWins="(SELECT COUNT(*) FROM duels d WHERE d.status='done' AND d.bot=0 AND d.wager=0 AND d.id<>NEW.id AND d.ends>NEW.ends-86400000 AND ((d.winner='challenger' AND d.challenger="+W+") OR (d.winner='opponent' AND d.opponent="+W+")))";
  const vsWins="(SELECT COUNT(*) FROM duels d WHERE d.status='done' AND d.bot=0 AND d.wager=0 AND d.id<>NEW.id AND d.ends>NEW.ends-86400000 AND ((d.winner='challenger' AND d.challenger="+W+" AND d.opponent="+L+") OR (d.winner='opponent' AND d.opponent="+W+" AND d.challenger="+L+")))";
  const winnerMm="(CASE NEW.winner WHEN 'challenger' THEN NEW.challenger_score ELSE NEW.opponent_score END)";
  schema.push("DROP TRIGGER IF EXISTS duel_pvp_reward");
  schema.push("CREATE TRIGGER IF NOT EXISTS duel_pvp_reward AFTER UPDATE OF status ON duels WHEN NEW.status='done' AND OLD.status='active' AND NEW.bot=0 AND NEW.wager=0 AND NEW.winner IN ('challenger','opponent') AND "+winnerMm+">="+DUEL_REWARD_MIN_MM+" AND "+dayWins+"<"+DUEL_REWARD_DAILY+" AND "+vsWins+"<"+DUEL_REWARD_PER_OPPONENT+" BEGIN UPDATE players SET coins=coins+"+byRank('coins')+",xp=xp+"+byRank('xp')+" WHERE id="+W+"; END");
}
