schema.push("DELETE FROM players WHERE id GLOB 'bot:*'");
const editableStats={coins:1000000,xp:10000000,rod:5,line:5,boots:5};
const playerFields="COALESCE((SELECT revision FROM character_resets WHERE character_resets.public_id=players.public_id),0) AS resetRevision,public_id,nickname,coins,xp,rod,line,boots,catches,CASE WHEN id LIKE 'guest:%' THEN 'Invité' ELSE 'Participant' END AS kind";
async function managePlayers(request,db,url,body){
  if(request.method==='GET'){
    const search=(url.searchParams.get('q')||'').trim().slice(0,80);
    const page=Number(url.searchParams.get('page')||0);
    if(!Number.isSafeInteger(page)||page<0||page>100000)return json({error:'Page invalide.'},400);
    const kind=url.searchParams.get('kind')||'all';
    if(!['all','guest','participant'].includes(kind))return json({error:'Filtre invalide.'},400);
    const where=kind==='guest'?" AND id LIKE 'guest:%'":kind==='participant'?" AND id NOT LIKE 'guest:%' AND id NOT LIKE 'bot:%'":" AND id NOT LIKE 'bot:%'";
    const {results}=await db.prepare('SELECT '+playerFields+',seen,created FROM players WHERE (instr(lower(nickname),lower(?))>0 OR public_id=?)'+where+' ORDER BY nickname COLLATE NOCASE,public_id LIMIT 31 OFFSET ?').bind(search,search,page*30).all();
    const totals=await db.prepare("SELECT COUNT(*) AS total,COALESCE(SUM(CASE WHEN id LIKE 'guest:%' THEN 1 ELSE 0 END),0) AS guests FROM players WHERE id NOT LIKE 'bot:%'").first();
    return json({players:results.slice(0,30),more:results.length>30,serverTime:Date.now(),totals:{all:totals.total,guest:totals.guests,participant:totals.total-totals.guests}});
  }
  if(request.method!=='POST')return json({error:'Méthode refusée.'},405);
  if(body.action==='resetFishing'){
    const all=body.scope==='all';
    if(!all&&body.scope!=='player')return json({error:'Sélection invalide.'},400);
    if(all?(body.confirmation!=='TOUS'||body.target!==undefined):
        (typeof body.target!=='string'||!body.target||body.confirmation!==body.target))
      return json({error:'Confirme les prises à réinitialiser.'},400);
    const affected=all?db.prepare('SELECT COUNT(*) AS total FROM players'):
      db.prepare('SELECT COUNT(*) AS total FROM players WHERE public_id=?').bind(body.target);
    const erase=all?db.prepare('DELETE FROM captures'):
      db.prepare('DELETE FROM captures WHERE player_id=(SELECT id FROM players WHERE public_id=?)').bind(body.target);
    const clear='UPDATE players SET points=0,catches=0,cast_started=0,cast_ticket=NULL,cast_data=NULL,last_landed=NULL';
    const update=all?db.prepare(clear):db.prepare(clear+' WHERE public_id=?').bind(body.target);
    const [count]=await db.batch([affected,erase,update]);
    if(!all&&!count.results[0].total)return json({error:'Profil introuvable.'},404);
    return json({reset:true,profiles:count.results[0].total});
  }
  if(body.action==='deleteMultiple'){
    const targets=body.targets;
    if(!Array.isArray(targets)||!targets.length||targets.length>20||targets.some(t=>typeof t!=='string'||!t||t.length>80)||new Set(targets).size!==targets.length)
      return json({error:'Sélection invalide (20 personnages maximum).'},400);
    if(body.confirmation!=='SUPPRIMER '+targets.length)return json({error:'Confirmation de suppression invalide.'},400);
    const marks=targets.map(()=>'?').join(',');
    const existing=await db.prepare('SELECT public_id FROM players WHERE public_id IN ('+marks+')').bind(...targets).all();
    if(existing.results.length!==targets.length)return json({error:'Un des personnages a changé ou a déjà été supprimé. Actualise la liste.'},409);
    const cleanup=[];
    const legacy=await db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='quest_claims'").first();
    if(legacy)cleanup.push(db.prepare('DELETE FROM quest_claims WHERE player_id IN (SELECT id FROM players WHERE public_id IN ('+marks+'))').bind(...targets));
    cleanup.push(db.prepare('DELETE FROM players WHERE public_id IN ('+marks+') RETURNING public_id').bind(...targets));
    const deleted=await db.batch(cleanup);
    return json({deleted:deleted.at(-1).results.length,accountPreserved:true});
  }
  if(typeof body.target!=='string'||!body.target||body.target.length>80)return json({error:'Choisis un joueur.'},400);
  if(body.action==='resetCharacter'){
    const revision=body.revision;
    if(body.confirmTarget!==body.target||!Number.isSafeInteger(revision)||revision<0)return json({error:'Confirme le personnage à remettre au niveau 1.'},400);
    const changed=await db.prepare(`INSERT INTO character_resets(public_id,revision)
      SELECT public_id,? FROM players WHERE public_id=? AND COALESCE((SELECT revision FROM character_resets WHERE public_id=?),0)=?
      ON CONFLICT(public_id) DO UPDATE SET revision=excluded.revision RETURNING revision`)
      .bind(revision+1,body.target,body.target,revision).all();
    if(!changed.results.length)return json({error:'Profil absent ou déjà réinitialisé. Actualise sa fiche.'},409);
    return json({reset:true,level:1});
  }
  if(body.action==='delete'){
    if(body.confirmTarget!==body.target)return json({error:'Confirme le profil à supprimer.'},400);
    const legacy=await db.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='quest_claims'").first();
    const cleanup=[];
    if(legacy)cleanup.push(db.prepare('DELETE FROM quest_claims WHERE player_id=(SELECT id FROM players WHERE public_id=?)').bind(body.target));
    cleanup.push(db.prepare('DELETE FROM players WHERE public_id=? RETURNING public_id').bind(body.target));
    const results=await db.batch(cleanup);
    if(!results.at(-1).results.length)return json({error:'Profil déjà supprimé.'},404);
    return json({deleted:true});
  }
  const {field,value,previous}=body;
  if(body.action!=='edit'||!Object.hasOwn(editableStats,field)||!Number.isSafeInteger(value)||value<0||
     value>editableStats[field]||!Number.isSafeInteger(previous))return json({error:'Valeur invalide.'},400);
  const {results}=await db.prepare('UPDATE players SET '+field+'=? WHERE public_id=? AND '+field+'=? RETURNING '+playerFields)
    .bind(value,body.target,previous).all();
  if(!results.length)return json({error:'Ce profil a changé. Recharge la liste avant de recommencer.'},409);
  return json({player:results[0]});
}
